from python_lib import HXGraders

def answercheck(e, ans):

  entries = [
    "hash_or_filename_1",
    "hash_or_filename_2",
    "hash_or_filename_3",
  ]

  options = {
    "entries": entries,
    "files_or_hashes": "files",   # alternative: "hashes"
    "credit_options": {
      "spaces": 0.9,
      "crlf": 0.8,
      "case": 0.6,
      "low_cutoff": 0.5,
      "high_cutoff": 0.9
    }
  }

  # This pulls from the python_lib.zip file in Files & Uploads.
  return HXGraders.fileComparisonGrader(ans, options)

$(document).ready(function(){
  console.log('outer ready');
});

function logThatThing(ThatThing){
  console.log(JSON.stringify(ThatThing));
  // Call the edX logging code.
  Logger.log("harvardx.StudioAdv.file_comparison", ThatThing);
}
